import{_ as e,c as r,o as i,ae as t}from"./chunks/framework.CHDT0Kbg.js";const m=JSON.parse('{"title":"隐私政策","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/privacy-policy.md","filePath":"zh-CN/guide/privacy-policy.md","lastUpdated":1795170900000}'),o={name:"zh-CN/guide/privacy-policy.md"};function l(c,a,h,n,s,d){return i(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="隐私政策" tabindex="-1">隐私政策 <a class="header-anchor" href="#隐私政策" aria-label="Permalink to &quot;隐私政策&quot;">​</a></h1><p>Persim 收集什么，什么只留在你的设备上。</p><h2 id="无需账户-没有云端资料" tabindex="-1">无需账户，没有云端资料 <a class="header-anchor" href="#无需账户-没有云端资料" aria-label="Permalink to &quot;无需账户，没有云端资料&quot;">​</a></h2><p>Persim 不需要登录，也不会为你创建在线账户。历史记录、书签、打开的标签、下载和 Cookie 都保存在你的 Mac 上。</p><h2 id="打开网页时用到的信息" tabindex="-1">打开网页时用到的信息 <a class="header-anchor" href="#打开网页时用到的信息" aria-label="Permalink to &quot;打开网页时用到的信息&quot;">​</a></h2><p>和所有浏览器一样，Persim 会把你访问的地址发送给对应网站。Persim 自身不会把你的浏览历史上传到服务器。</p><h2 id="你可以开启的网络功能" tabindex="-1">你可以开启的网络功能 <a class="header-anchor" href="#你可以开启的网络功能" aria-label="Permalink to &quot;你可以开启的网络功能&quot;">​</a></h2><ul><li>广告拦截订阅会联网更新规则；更新失败时，已保存的规则继续生效。</li><li>油猴脚本和你下载的文件，只在你主动操作时才会获取。</li><li>在地址栏输入时会向你选择的搜索引擎获取搜索建议。</li></ul><h2 id="本地权限" tabindex="-1">本地权限 <a class="header-anchor" href="#本地权限" aria-label="Permalink to &quot;本地权限&quot;">​</a></h2><p>摄像头、麦克风和文件权限按网站分别记住，可在设置里修改。定位与通知由 macOS 管理。无痕窗口（⌘⇧N）不会写入历史记录或会话。</p><h2 id="第三方网站" tabindex="-1">第三方网站 <a class="header-anchor" href="#第三方网站" aria-label="Permalink to &quot;第三方网站&quot;">​</a></h2><p>你访问的网站由他人运营，遵循各自的隐私政策。Persim 的内置页面不会追踪你。</p><h2 id="联系我们" tabindex="-1">联系我们 <a class="header-anchor" href="#联系我们" aria-label="Permalink to &quot;联系我们&quot;">​</a></h2><p>隐私相关问题：<strong><a href="mailto:persim@w3cub.com" target="_blank" rel="noreferrer">persim@w3cub.com</a></strong>。</p>',14)])])}const u=e(o,[["render",l]]);export{m as __pageData,u as default};
